<section class="section"><header class="admin-header"><h1>Tickets</h1><a href="ticket_create.php" class="btn">Nuevo ticket</a></header><form method="get" class="admin-form"><input name="customer" placeholder="Cliente, correo o teléfono" value="<?php echo htmlspecialchars($filters['customer'], ENT_QUOTES, 'UTF-8'); ?>"><select name="scope"><option value="open">Abiertos</option><option value="all" <?php echo $filters['scope'] === 'all' ? 'selected' : ''; ?>>Todos</option></select><button class="btn">Buscar</button></form><p><?php echo (int) $total; ?> ticket(s)</p><table class="table"><thead><tr><th>ID</th><th>Cliente</th><th>Tipo</th><th>Estado</th><th>Fecha</th></tr></thead><tbody><?php foreach ($tickets as $ticket): ?><tr><td><a href="ticket_view.php?id=<?php echo (int) $ticket['id']; ?>">#<?php echo (int) $ticket['id']; ?></a></td><td><?php echo htmlspecialchars($ticket['customer_name'], ENT_QUOTES, 'UTF-8'); ?></td><td><?php echo htmlspecialchars($ticket['consultation_type'], ENT_QUOTES, 'UTF-8'); ?></td><td><?php echo htmlspecialchars($ticket['status'], ENT_QUOTES, 'UTF-8'); ?></td><td><?php echo htmlspecialchars((string) $ticket['created_at'], ENT_QUOTES, 'UTF-8'); ?></td></tr><?php endforeach; ?></tbody></table><?php if ($totalPages > 1): ?><nav><?php for ($pageNumber = 1; $pageNumber <= $totalPages; $pageNumber++): ?><a href="?page=<?php echo $pageNumber; ?>&amp;scope=<?php echo urlencode($filters['scope']); ?>&amp;customer=<?php echo urlencode($filters['customer']); ?>"><?php echo $pageNumber; ?></a> <?php endfor; ?></nav><?php endif; ?></section>
